module Fuaran.UI.JsonDecode.Tests.SchemaConformance

// ============================================================================
//  Schema-conformance acceptance against the corpus (Phase 96).
//
//  The canonical wire-format JSON Schema lives at
//  `wire-format-fixtures/schema.json` (generated by Fuaran.UI.Ops.SchemaGen).
//  This suite proves it is a faithful, machine-readable expression of the same
//  contract JsonDecode enforces, using an OFF-THE-SHELF Draft 2020-12 validator
//  (JsonSchema.Net) — so passing here means the schema is a genuine drop-in for
//  external validators / editor tooling / provider-native constrained emission.
//
//  Three assertions:
//    1. Every accept-fixture (node-round-trip / op-round-trip) VALIDATES against
//       the schema — mirrors `JsonDecode.decode* = Ok`.
//    2. Every reject-fixture FAILS the schema (or is not parseable JSON, the
//       INVALID_JSON case) — mirrors `JsonDecode.decode* = Error`. The one
//       exception is the named `schemaInexpressibleRejects` set: rules Draft
//       2020-12 provably cannot state (cross-field ordering; recursion depth),
//       pinned inversely so the exemption cannot outlive its reason.
//    3. Stale-schema guard: the committed schema.json is byte-identical to a
//       fresh `SchemaGen.wireFormatSchema` — the regenerate-and-diff guard that
//       keeps the schema co-updated with Types.fs (WIRE_FORMAT.md §11). If this
//       fails, regenerate with
//       `dotnet run --project src/Fuaran.UI.JsonDecode.Tests -- --emit-corpus ..\wire-format-fixtures`.
//
//  The suite reads the emitted corpus + schema.json, never the F# fixture
//  VALUES, so the assertions are exactly what a second host (e.g. the Wave 9 TS
//  decoder, or any third-party validator) would run.
// ============================================================================

open System.IO
open System.Text.Json
open Expecto
open Json.Schema
open Fuaran.UI.Ops

let private corpusRoot, corpusEntries = Corpus.load ()

let private schemaPath = Path.Combine(corpusRoot, "schema.json")
let private schemaText = File.ReadAllText schemaPath
let private schema = JsonSchema.FromText schemaText

/// Evaluate a wire payload against the canonical schema. `None` ⇒ the input is
/// not parseable JSON (the INVALID_JSON surface — a rejection). `Some isValid`
/// ⇒ parsed + schema-evaluated.
let private validate (wire: string) : bool option =
    // Parsed at the wire format's own syntactic bound (`Corpus.wireJsonOptions`),
    // not System.Text.Json's 64-level default. On the default this function
    // returned `None` — "not parseable JSON" — for every §21 depth fixture,
    // which read as a REJECTION: the accept-fixture leg failed outright, and the
    // reject legs passed for a reason that had nothing to do with the schema.
    let parsed =
        try
            Some(JsonDocument.Parse(wire, Corpus.wireJsonOptions))
        with _ ->
            None

    match parsed with
    | None -> None
    | Some doc ->
        use doc = doc
        let result = schema.Evaluate(doc.RootElement, EvaluationOptions())
        Some result.IsValid

let private acceptEntries =
    corpusEntries
    |> List.filter (fun e -> e.Kind = "node-round-trip" || e.Kind = "op-round-trip")

let private rejectEntries =
    corpusEntries |> List.filter (fun e -> e.Kind = "reject")

let private acceptTest (e: Corpus.FixtureEntry) : Test =
    testCase (sprintf "accept — %s (%s) — validates against schema" e.Description e.Id) (fun () ->
        let wire = Corpus.readPayload corpusRoot e.InputFile

        match validate wire with
        | Some true -> ()
        | Some false -> failtestf "schema REJECTED an accept-fixture (JsonDecode accepts it)\n  input: %s" wire
        | None -> failtestf "accept-fixture is not parseable JSON\n  input: %s" wire)

/// Reject fixtures whose rule Draft 2020-12 **provably cannot express**, so the
/// decoder is their only enforcer. Named, never counted — a fixture MOVING onto
/// or off this list is the interesting event, and a bare exemption count hides
/// it. The same posture the generated-layer seam takes for its policy-owned
/// residue (`GeneratedLayerTests.fs`).
///
/// - `reject-daterange-unordered` (Phase 725): `DateRange.value` must satisfy
///   `from <= to`. Draft 2020-12 has no keyword that relates two sibling
///   property values, so the payload is a well-formed `{from, to}` object by
///   every shape rule the schema can state. Ordering is decoder policy.
///
/// - `reject-fieldrule-length-unordered` (Phase 864): `FieldRule` must satisfy
///   `minLength <= maxLength` — the `reject-daterange-unordered` rule above,
///   applied to a length pair, and inexpressible for the identical reason.
///   Note its two SIBLING refusals are NOT here and must not be added: "a rule
///   must constrain something" is an `anyOf` over five property names, and the
///   `validation` / `constraints` / `validate` near miss is a `not: required`,
///   so both are stated in the schema and both fail it. Only the relation
///   between two values escapes the dialect.
///
/// - `reject-limit-node-depth` / `reject-limit-op-depth` (Phase 781, §21):
///   nesting deeper than `WireLimits.MaxDepth`. Draft 2020-12 recurses through
///   `$ref` and has no keyword that bounds how many times — a depth limit is
///   not a shape, and the payloads are legal by every shape rule the schema can
///   state. Their SIBLINGS `reject-limit-json-depth{,-at-max}` are NOT here and
///   must not be added: those breach (or sit at) the syntactic bound, so the
///   parser refuses the first outright and the schema refuses the second on
///   shape — a bare array is not a node. Only the semantic depth rule escapes
///   the dialect. Both were latent until fuaran#1094 parsed at the wire bound
///   rather than System.Text.Json's 64-level default; before that the harness's
///   own parser refused them and the exemption was invisible.
///
/// - `reject-limit-tree-item-depth` (Phase 1120, §21.5): the same rule on a THIRD
///   axis — `TreeItem` rows nested past `WireLimits.MaxDepth` inside one node.
///   The schema models the recursion exactly as it models node nesting, by name,
///   and is exactly as unable to bound it. Worth stating rather than folding
///   into the entry above, because the two are not the same fixture class in
///   every respect: this one exceeds NO node bound at all (the whole hierarchy
///   is one node), so it is schema-valid AND node-depth-valid, and only the
///   item-axis counter refuses it.
///
/// - `reject-chart-annotation-date-unparseable` (Phase 1491, §4l): an event
///   marker's `Date` address naming no calendar day. This one is here by a
///   DELIBERATE MODELLING CHOICE rather than by a limit of the dialect, and it is
///   the first entry of which that is true — so it is worth stating plainly.
///   Draft 2020-12 has `pattern`, and a regex over `YYYY-MM-DD` is writable; what
///   it cannot do is know that February has 28 days. A pattern would therefore
///   admit `2026-02-30` while the decoder refuses it, and the schema would then
///   say something DIFFERENT from the decoder rather than something LESS —
///   which is the property the whole schema leg exists to preserve, and the same
///   reason `ChartAnnotation.value` takes a bare `type: number`. If a future
///   dialect can state the calendar, the slot gains the constraint and this
///   entry goes, exactly as the inverse pin below intends.
///
/// - `reject-chart-annotation-range-unordered` (Phase 1492, §4l): a range
///   band's pair running backwards. This is the ORIGINAL entry's own limit
///   arriving at a second slot — Draft 2020-12 has no keyword that compares two
///   SIBLING members, which is exactly why `reject-daterange-unordered` has sat
///   here since Phase 725. Nothing about the shape is unstated: both ends are
///   `finiteNumber`, and it is the relation between them the dialect cannot
///   name.
///
/// Each entry is asserted schema-VALID below — the INVERSE pin. If the schema
/// ever gains the power to refuse one of these, this test fails and the list
/// shrinks deliberately rather than the exemption quietly outliving its reason.
let private schemaInexpressibleRejects: Set<string> =
    set
        [ "reject-chart-annotation-date-unparseable"
          "reject-chart-annotation-range-unordered"
          "reject-daterange-unordered"
          // Phase 2591 — a name unique across a list of records: `uniqueItems` compares whole
          // items, and two citations with one name differ in their references.
          "reject-markdown-citation-name-repeated"
          // Phase 2571 — the option-group refusals are relations ACROSS the
          // document (a value unique over every group's list; a value one of the
          // sibling `source`'s options carries). `uniqueItems` reaches one array
          // only, and nothing in the dialect joins a member to a sibling's values.
          "reject-2571-select-group-value-twice"
          "reject-2571-select-group-value-unknown"
          // fuaran#1085 retired `reject-transform-source-empty-wrapper` from
          // this list with the fixture itself: the shape the schema could not
          // refuse is one the DECODER no longer refuses either.
          "reject-fieldrule-length-unordered"
          "reject-limit-node-depth"
          "reject-limit-node-depth-switch-case"
          "reject-limit-node-depth-errorboundary-fallback"
          "reject-limit-op-depth"
          "reject-limit-tree-item-depth"

          // ─── Phase 1521 — the §20 rows a JSON Schema validator cannot see ──
          //
          // These are not a modelling gap a better `SchemaGen` would close:
          // they are refusals at the JSON SYNTAX layer, and a schema validator by
          // construction runs over an ALREADY-PARSED document. By the time it
          // looks, the parser has resolved the duplicate member to whichever one
          // it kept, and a lone surrogate is simply a string. §20 exists precisely
          // because that layer was unconstrained, and the decoder — not the schema
          // — is its enforcement point.
          //
          // The remaining §20 vectors are NOT here, and the discriminator is worth
          // keeping: `+1`, `01`, `.5`, `1.`, `3e`, a bare `NaN`, a raw C0 and
          // trailing content are all UNPARSEABLE, so the ordinary path's `None`
          // arm covers them.
          "reject-json-duplicate-key"
          "reject-json-lone-high-surrogate"
          "reject-json-lone-low-surrogate"
          "reject-json-surrogate-pair-split"
          // Phase 2286 — the two NUMBER refusals the parse move added, the same
          // syntax-layer reason: `1e999` (§20.2 row 7) and an integer token past
          // 2^53 that is not a canonical float layout (§2 rule 5) are both
          // well-formed RFC 8259 numbers, so the validator's own parser admits
          // them and a JSON Schema `number` / `{}` slot has nothing to refuse.
          // The refusal is the substrate grammar's value rule, at the decoder.
          "reject-json-integer-beyond-int53"
          "reject-json-number-overflow-exponent"

          // §7.1's range half USED TO BE HERE, and Phase 1666 retired the entry
          // exactly as the note predicted: "it fails the moment `SchemaGen` emits
          // those bounds, which is when this entry should go". §21.9 bounds
          // `Skeleton.rows` at 10 000 and `SchemaGen` states it as a `maximum`,
          // so `reject-int-slot-out-of-range` (`rows: 1e10`) is now refused by
          // the schema and the inverse assertion caught the stale exemption on
          // the first run.
          //
          // Worth being precise about WHAT closed, because it is less than the
          // old note's framing suggests: the fixture is caught by a §21 RESOURCE
          // ceiling that happens to sit on the slot it probes, not by §7.1's
          // 32-bit range being expressed. Every other typed integer slot still
          // carries no `minimum` / `maximum`, so §7.1's range half remains
          // schema-inexpressible in general — it simply has no fixture of its own
          // any more. Its sibling `reject-int-slot-fractional` needed no entry
          // either way: `"type":"integer"` already refuses `2.5`.

          // ─── Fuaran-UI Phase 1534 — `Binding.Expr`'s two refusals ─────────
          //
          // Both are decoder-only by construction, not a modelling gap a better
          // `SchemaGen` would close.
          //
          // The `col` one asks whether a `{"$type":"col"}` object appears
          // ANYWHERE inside a recursive expression whose every operator arm can
          // nest further — an unbounded existential over a recursive structure,
          // for which JSON Schema has no operator.
          //
          // The unbound-param one is harder still: it is a CROSS-FIELD
          // constraint — every `param` name reachable in `expr` must appear in
          // this binding's own `params` array — with the two sides at different
          // depths of one object. Neither `$ref` nor `if`/`then` can carry a
          // value out of one member into a predicate over another.
          //
          // Filed here with the reason rather than left silently passing;
          // §3.3.2 of the specification is the enforcement point, and every
          // host's decoder is where it is enforced.
          "reject-expr-col-reference"
          "reject-expr-unbound-param"

          // ─── Fuaran-UI Phase 1662 — §21.8 on the pipeline surface ─────────
          //
          // The `reject-limit-node-depth` entry's limit, on the expression
          // axis: "at most 512 nodes anywhere inside this recursive
          // expression" is a COUNT over a `$ref` recursion, and Draft 2020-12
          // has no keyword that bounds how many times it recurses. The three
          // payloads are legal by every shape rule the schema can state — a
          // `coalesce` over 512 well-formed operands is a well-formed
          // `coalesce` — which is exactly why the bound has to live in the
          // decoder and be pinned by the corpus.
          //
          // Note `maxItems` is NOT the missing keyword and must not be reached
          // for: it would bound ONE array, and the limit is over the whole
          // expression however the nodes are distributed across nested
          // operators.
          "reject-limit-expr-nodes-derive"
          "reject-limit-expr-nodes-filter"
          "reject-limit-expr-nodes-transform-bypass"

          // ─── Fuaran-UI Phase 1537 — Confirm's depth-one bound ─────────────
          //
          // The SAME shape as `reject-expr-col-reference` above, one union over:
          // "does a `{"$type":"Confirm"}` appear ANYWHERE reachable from this
          // continuation", where `Chain` lets it nest arbitrarily deep. An
          // unbounded existential over a recursive structure, and JSON Schema
          // has no operator for it.
          //
          // It is expressible only by DUPLICATING the whole `Action` union under
          // a second confirm-free name and pointing both continuations at that —
          // which would double the emitted schema and put two definitions of
          // every action arm in a published artefact, so that the next case
          // added to one and not the other is a silent divergence in a document
          // external tooling reads. The decoder is the authority
          // (WIRE_FORMAT §3.6.22 says so normatively), exactly as it is for the
          // §16 field aliases the schema likewise does not carry.
          //
          // The MISSING_FIELD sibling `reject-confirm-missing-onconfirm` is NOT
          // here: `required` expresses it, and the ordinary path asserts it.
          "reject-confirm-nested"

          // Fuaran-UI Phase 1538 — `Binding.Local`'s two refusals. Unlike the
          // two above these ARE expressible in principle, and are filed here for
          // the `reject-int-slot-out-of-range` reason rather than a dialect one:
          // `not: { required: ["onCommit", "commitTo"] }` would state the
          // exclusion, and an `allOf` narrowing the codec's `$ref` to the
          // `Number` arm would state the admitted set. Neither is emitted today.
          //
          // Filed with the reason rather than left silently passing, and pinned
          // INVERSELY like every entry here — so the day `SchemaGen` states
          // either one, this test fails and the entry goes, instead of the
          // exemption outliving its reason.
          "reject-local-codec-no-inverse"
          "reject-local-oncommit-and-committo"

          // ─── Phase 1821 — the 0.28.0 column-member rename's ambiguity pair ─
          //
          // A `project` step, or a `sort` key, carrying BOTH the canonical
          // spelling (`columns` / `column`) and its decode alias (`cols` /
          // `col`). Filed for the `reject-local-oncommit-and-committo` reason —
          // expressible in principle, not emitted — rather than a dialect
          // limit: `not: { required: ["cols"] }` on the `project` arm states
          // exactly this exclusion and Draft 2020-12 has the keyword.
          //
          // Two things keep it unemitted, and they compound. The schema does
          // not set `additionalProperties: false` anywhere, matching the
          // decoder's tolerance of unknown keys, so an alias reads to it as an
          // ordinary unknown member. And the emitted schema is consumed by
          // provider structured-output dialects whose keyword subsets are
          // narrow — the same argument already recorded for `window.n`'s
          // `if`/`then` relation, and the reason the schema is content to say
          // LESS than the decoder here rather than something DIFFERENT. An
          // alias is a decode-only spelling the encoder never emits, so a
          // schema that never mentions it is still a correct description of
          // what a conformant emitter produces.
          //
          // Pinned INVERSELY like every entry here: the day `SchemaGen` states
          // the exclusion, this fails and the two entries go.
          "reject-transform-project-columns-and-cols"
          "reject-transform-sort-key-column-and-col"

          // ─── Phase 2206 — the timestamp unit's refusals ────────────────────
          //
          // All six sit inside a Transform's EMBEDDED source, which `SchemaGen`
          // does not model at all: the schema describes the pipeline steps and
          // leaves the source an open object, because the columnar wire belongs
          // to the column codec (WIRE_FORMAT §3.6.25) and not to this tree.
          // Five of them are cross-field besides: whether a cell's text is
          // canonical for its unit depends on the `schema` entry of the SAME
          // NAME in a sibling array, a correlation by value that Draft 2020-12
          // cannot carry from one array into a predicate over another. The
          // sixth, the unknown unit tag, is expressible in principle (an `enum`
          // over `schema[].type`) and is filed for the
          // `reject-local-oncommit-and-committo` reason: stating it means
          // modelling the source, which is a schema change of its own and not
          // this phase's. Pinned INVERSELY like every entry here.
          "reject-transform-timestamp-fractional-second"
          "reject-transform-timestamp-ms-epoch-before-0000"
          "reject-transform-timestamp-ms-finer-fraction"
          "reject-transform-timestamp-ms-padded-fraction"
          "reject-transform-timestamp-unknown-unit"
          "reject-transform-timestamp-us-finer-fraction"

          // ─── Phase 2484 — the int column's 32-bit bound ────────────────────
          //
          // Inside the same EMBEDDED source `SchemaGen` leaves open, and
          // cross-field on the same ground as the six above: whether a number
          // is in range depends on the `schema` entry of the same name in a
          // sibling array. Pinned INVERSELY like every entry here.
          "reject-transform-int-above-int32"
          "reject-transform-int-below-int32"
          "reject-transform-int-fractional" ]

// Phase 1068 — `schemaTypeErasedBindingRejects` is GONE, and its deletion is the
// point rather than a tidy-up. Phase 1064 found four reject fixtures the emitted
// schema *could* express and did not, because `Binding<'T>` was emitted ONCE,
// type-erased: every slot was `{"$ref":"#/$defs/Binding"}` and that definition's
// `Static` arm was `"value": true` — any JSON at all. They were kept in their own
// named set rather than folded into `schemaInexpressibleRejects` above, because
// that list is a statement about the DIALECT and a modelling decision filed there
// would quietly have become a law; and they were pinned INVERSELY — asserted
// schema-VALID — so the exemption could not outlive its reason.
//
// It did not. `SchemaGen` now emits one `$def` per instantiated element type
// (`Binding_float`, `Binding_int`, `Binding_str`, …) and points each slot at its
// own, as does the IDL's schema leg in the same change-set. The four —
// `reject-binding-float-bool`, `reject-binding-float-string`,
// `reject-binding-int-bool`, `reject-binding-int-sentinel-string` — are refused
// by the published schema now and take the ORDINARY reject path below, which is
// the assertion that matters. Their sibling `reject-binding-float-sentinel-case`
// was never on the list: it reaches the slot through §3.6's bare-scalar arm,
// which the schema never modelled, so the schema always refused it on shape.

let private rejectTest (e: Corpus.FixtureEntry) : Test =
    if schemaInexpressibleRejects.Contains e.Id then
        testCase
            (sprintf "reject — %s (%s) — decoder-only rule, schema cannot express it" e.Description e.Id)
            (fun () ->
                let wire = Corpus.readPayload corpusRoot e.InputFile

                match validate wire with
                | Some true -> ()
                | Some false ->
                    failtestf
                        "the schema now REFUSES '%s' — remove it from schemaInexpressibleRejects; the exemption has outlived its reason\n  input: %s"
                        e.Id
                        wire
                | None ->
                    failtestf "exempt reject-fixture '%s' is not parseable JSON — it belongs in the ordinary set" e.Id)
    else
        testCase (sprintf "reject — %s (%s) — fails the schema" e.Description e.Id) (fun () ->
            let wire = Corpus.readPayload corpusRoot e.InputFile

            match validate wire with
            // Unparseable JSON OR schema-invalid both count as a rejection,
            // consistent with JsonDecode returning Error.
            | None -> ()
            | Some false -> ()
            | Some true -> failtestf "schema ACCEPTED a reject-fixture (JsonDecode rejects it)\n  input: %s" wire)

[<Tests>]
let acceptConformance =
    acceptEntries
    |> List.map acceptTest
    |> testList "Fuaran.UI.Ops.SchemaGen — accept-fixtures validate (corpus)"

[<Tests>]
let rejectConformance =
    rejectEntries
    |> List.map rejectTest
    |> testList "Fuaran.UI.Ops.SchemaGen — reject-fixtures fail the schema (corpus)"

[<Tests>]
let staleSchemaGuard =
    testList
        "Fuaran.UI.Ops.SchemaGen — stale-schema guard"
        [ testCase "committed schema.json is byte-identical to SchemaGen.wireFormatSchema" (fun () ->
              Expect.equal
                  schemaText
                  SchemaGen.wireFormatSchema
                  "wire-format-fixtures/schema.json is stale relative to Types.fs / SchemaGen — regenerate with `dotnet run --project src/Fuaran.UI.JsonDecode.Tests -- --emit-corpus ..\\wire-format-fixtures`"

              // The schema must itself be a parseable, well-formed JSON Schema —
              // FromText above would have thrown otherwise; assert it loaded.
              Expect.isFalse (isNull (box schema)) "schema parsed as a JSON Schema document") ]

// ─── Fuaran-UI Phase 1571 — the typed pipeline step union ───────────────────
//
// `Binding.Transform.pipeline` was `{"type":"array","items":true}`: the step
// shapes `JsonDecode` enforces (through `Fuaran.Compute.DataFrameCodec`) reached
// the published schema as untyped, so a schema-bound emitter had no constraint
// to honour and the generated catalogue taught `pipeline:any[]`. `SchemaGen`
// now emits the closed `TransformStep` union. Two claims hold it honest, and
// they are different claims: the first that the union COVERS the DU, the second
// that a member the decoder requires is actually refused.

open Microsoft.FSharp.Reflection

/// The `$type` const of every alternative of a named union `$def`, read from
/// the EMITTER rather than the committed artefact.
///
/// The subject of the exhaustiveness claim is what `SchemaGen` produces; the
/// artefact's own staleness is the guard at the foot of this file, and going
/// through the file here would make this test pass on a stale `schema.json`
/// whose union no longer matches the generator (proved: dropping an arm from
/// `SchemaGen` and NOT regenerating left it green). The two together bind the
/// published artefact to the DU; separately, neither does.
let private unionTags (defName: string) : Set<string> =
    use doc = JsonDocument.Parse SchemaGen.wireFormatSchema

    let def = doc.RootElement.GetProperty("$defs").GetProperty defName

    def.GetProperty("oneOf").EnumerateArray()
    |> Seq.map (fun alt ->
        match alt.GetProperty("properties").GetProperty("$type").GetProperty("const").GetString() with
        | null -> failtestf "an alternative of the '%s' union carries a non-string `$type` const" defName
        | tag -> tag)
    |> Set.ofSeq

/// The wire tag a `Fuaran.Compute.Transform` case encodes as. Every one
/// of the seventeen is its case name with a lowered initial — `Filter` → `filter`,
/// `GroupBy` → `groupBy` — which is what `DataFrameCodec.encodeTransform` writes
/// and `decodeTransform` reads back, so the mapping is derived rather than
/// transcribed and a case added to Core arrives here on its own.
let private wireTagOfCaseName (name: string) : string =
    string (System.Char.ToLowerInvariant name[0]) + name.Substring 1

let private transformDuTags: Set<string> =
    FSharpType.GetUnionCases typeof<Fuaran.Compute.Transform>
    |> Array.map (fun c -> wireTagOfCaseName c.Name)
    |> Set.ofArray

/// A minimal node whose only `Transform` binding carries `step` as its whole
/// pipeline. Hand-built rather than spliced out of a corpus fixture: the claim
/// is about ONE step object, and every other part of this document is held
/// fixed across a probe's two halves so a refusal is attributable to the step.
let private pipelineNode (step: string) : string =
    sprintf
        """{"id":"n1","kind":{"$type":"Badge","label":{"$type":"Bound","binding":{"$type":"Transform","pipeline":[%s],"source":{"columns":{"km":[1,2],"split":[4.8,5.1]}}}},"variant":"Info"}}"""
        step

/// One step probe. `Complete` is asserted schema-VALID **and** decodable, so a
/// refusal of `Defective` is evidence about the missing member and not about
/// some other defect in the hand-built document.
type private StepProbe =
    { Id: string
      Why: string
      Defective: string
      Complete: string }

let private completeWindowStep =
    """{"$type":"window","partitionBy":["km"],"orderBy":[{"column":"km","dir":"asc"}],"fn":"cumulSum","of":"split","as":"cumulative"}"""

let private completeGroupByStep =
    """{"$type":"groupBy","keys":[],"aggs":[{"name":"n","fn":"count","of":"km"}]}"""

let private stepProbes: StepProbe list =
    [
      // The motivating instance: the 2026-09-07 comparative rerun lost
      // `tier-a-059` (the window / running-total probe) to
      // `source.pipeline: missing field: fn`, and the schema arm could not
      // recover it, because the schema said nothing at all about a window step.
      { Id = "window-missing-fn"
        Why = "a window step with no `fn`"
        Defective =
          """{"$type":"window","partitionBy":["km"],"orderBy":[{"column":"km","dir":"asc"}],"of":"split","as":"cumulative"}"""
        Complete = completeWindowStep }
      // The same member name at the other slot that reads it — a `groupBy`
      // aggregate. Same decoder error text, different position, so the two are
      // not one probe.
      { Id = "groupby-agg-missing-fn"
        Why = "a groupBy aggregate with no `fn`"
        Defective = """{"$type":"groupBy","keys":[],"aggs":[{"name":"n","of":"km"}]}"""
        Complete = completeGroupByStep }
      // Closedness in the two directions a union can be open: an unrecognised
      // discriminator, and none at all. Both are decoder refusals carrying their
      // own didactic (`decodeTransform`'s op roster); neither was expressible
      // while the slot was `items: true`.
      { Id = "unknown-step-type"
        Why = "a step whose `$type` names no op"
        Defective = """{"$type":"aggregate","keys":[],"aggs":[]}"""
        Complete = completeGroupByStep }
      { Id = "step-without-discriminator"
        Why = "a step object with no `$type`"
        Defective = """{"columns":[{"a":"km","b":"km"}]}"""
        Complete = """{"$type":"project","columns":[{"a":"km","b":"km"}]}""" }
      // An enum value outside the closed window vocabulary. The legacy `cumSum`
      // spelling the decoder still admits is deliberately NOT the probe here —
      // that one is a §16 alias, and the schema carries canonical spellings only.
      { Id = "unknown-window-fn"
        Why = "a window `fn` outside the closed vocabulary"
        Defective =
          """{"$type":"window","partitionBy":["km"],"orderBy":[{"column":"km","dir":"asc"}],"fn":"runningTotal","of":"split","as":"cumulative"}"""
        Complete = completeWindowStep } ]

[<Tests>]
let transformStepUnion =
    testList
        "Fuaran.UI.Ops.SchemaGen — TransformStep is the pipeline's typed step union"
        [ testCase "the emitted union is exhaustive over Fuaran.Compute.Transform" (fun () ->
              let emitted = unionTags "TransformStep"

              let missing = Set.difference transformDuTags emitted
              let extra = Set.difference emitted transformDuTags

              Expect.isEmpty
                  missing
                  (sprintf
                      "these Fuaran.Compute.Transform cases have NO arm in the emitted TransformStep union, so the published schema types them as nothing and a schema-bound emitter cannot spell them: %s"
                      (String.concat ", " missing))

              Expect.isEmpty
                  extra
                  (sprintf
                      "the emitted TransformStep union declares arms Fuaran.Compute.Transform has no case for, so the schema admits steps the decoder refuses: %s"
                      (String.concat ", " extra)))

          for p in stepProbes do
              testCase (sprintf "the schema refuses %s (%s)" p.Why p.Id) (fun () ->
                  match validate (pipelineNode p.Complete) with
                  | Some true -> ()
                  | Some false ->
                      failtestf
                          "the CONTROL for '%s' does not validate against the schema — the probe proves nothing until it does\n  %s"
                          p.Id
                          (pipelineNode p.Complete)
                  | None -> failtestf "the control for '%s' is not parseable JSON" p.Id

                  match JsonDecode.decodeNode (pipelineNode p.Complete) with
                  | Ok _ -> ()
                  | Error e -> failtestf "the CONTROL for '%s' does not DECODE: %A" p.Id e

                  match validate (pipelineNode p.Defective) with
                  | Some false -> ()
                  | Some true ->
                      failtestf
                          "the schema ACCEPTED %s — a schema-bound emitter is unconstrained there and the decoder is the only refusal\n  %s"
                          p.Why
                          (pipelineNode p.Defective)
                  | None -> failtestf "the probe for '%s' is not parseable JSON" p.Id)

          // Fuaran.Compute 0.43.0's three steps, as the producer's own codec writes them —
          // every optional member present and every slot a `$param`, so the arms are held to
          // the encoder's widest output rather than to a hand-written document that might
          // only exercise the narrow one. Each must validate AND decode.
          testCase "the define, fit and predict arms admit the producer's encoding of each step" (fun () ->
              let ols = Fuaran.Compute.FitSpec.ols "split" [ "km", Fuaran.Compute.Col "km" ]

              let fit: Fuaran.Compute.FitSpec =
                  { ols with
                      Weights = Some "km"
                      Offset = Some(Fuaran.Compute.Col "km")
                      Ridge = Some(Fuaran.Compute.Slot.Param "r")
                      Control =
                          { MaxIter = Fuaran.Compute.Slot.Param "m"
                            Tol = Fuaran.Compute.Slot.Param "t" }
                      StdErrors = Fuaran.Compute.FitStdErrors.HC1 }

              let scored = Fuaran.Compute.PredictSpec.ofTraining fit (Fuaran.Core.Ref "training")

              let steps: Fuaran.Compute.Transform list =
                  [ Fuaran.Compute.Define
                        { Name = "f"
                          Params =
                            [ { Name = "x"
                                Default = Some(Fuaran.Compute.Slot.Lit(Fuaran.Core.Int 1)) }
                              { Name = "y"
                                Default = Some(Fuaran.Compute.Slot.Param "p") } ]
                          Body = Fuaran.Compute.Call("g", [ Fuaran.Compute.Arg "x" ]) }
                    Fuaran.Compute.Fit fit
                    Fuaran.Compute.Fit
                        { fit with
                            Family = Fuaran.Compute.FitFamily.Tweedie 1.5
                            Link = Fuaran.Compute.FitLink.Log }
                    Fuaran.Compute.Predict
                        { scored with
                            Interval =
                                Some
                                    { Kind = Fuaran.Compute.IntervalKind.Prediction
                                      Level = Fuaran.Compute.Slot.Param "l" } } ]

              for step in steps do
                  let wire = Fuaran.Compute.DataFrameCodec.encodePipeline [ step ]
                  let node = pipelineNode (wire.Substring(1, wire.Length - 2))

                  match validate node with
                  | Some true -> ()
                  | Some false -> failtestf "the schema REFUSED the producer's encoding\n  %s" node
                  | None -> failtestf "not parseable JSON\n  %s" node

                  match JsonDecode.decodeNode node with
                  | Ok _ -> ()
                  | Error e -> failtestf "the producer's encoding does not DECODE: %A\n  %s" e node) ]

// ─── The constrained-emitter acceptance leg (Phase 2451, WIRE_FORMAT §11.4) ───
//
// The manifest declares emitter profiles: per lineage, revisions oldest first,
// each naming its axes, its declared subset and its vectors, and per codec host
// the oldest revision that host still accepts (§15.6). This leg is this host's
// answer: for every lineage it reads every revision from `oldestAccepted.fuaran`
// onward and asserts each vector is a row of a family every codec host reads,
// integer-only when the revision claims it, inside the revision's subset, valid
// against the schema, and ACCEPTED — re-encoded byte-identical (a round-trip row)
// or normalised to its expected bytes (an alias-shim row, §16). Like the rest of
// this suite it reads the committed corpus, never the F# fixture values.

/// This host's token in the §11.0 roster and in every `oldestAccepted` record.
let private thisHost = "fuaran"

/// `true` when the bytes carry a number token with a fraction or an exponent
/// anywhere outside a string — the `integer-only` axis reads the TOKEN, not the
/// value, so `2.0` is refused although it is whole.
let carriesNonIntegerNumber (wire: string) : bool =
    let mutable inString = false
    let mutable escaped = false
    let mutable inNumber = false
    let mutable found = false

    for c in wire do
        if inString then
            if escaped then
                escaped <- false
            elif c = '\\' then
                escaped <- true
            elif c = '"' then
                inString <- false
        elif c = '"' then
            inString <- true
            inNumber <- false
        elif c = '-' || System.Char.IsDigit c then
            inNumber <- true
        elif inNumber && (c = '.' || c = 'e' || c = 'E') then
            found <- true
        else
            inNumber <- false

    found

/// Every `TreeOp` discriminator an op document carries: its own, and every
/// member of a `Batch` at any depth.
let rec opTagsOf (el: JsonElement) : string list =
    match el.TryGetProperty "$type" with
    | true, t when t.ValueKind = JsonValueKind.String ->
        let tag = string (t.GetString())

        let nested =
            match tag, el.TryGetProperty "ops" with
            | "Batch", (true, arr) when arr.ValueKind = JsonValueKind.Array ->
                arr.EnumerateArray() |> Seq.collect opTagsOf |> List.ofSeq
            | _ -> []

        tag :: nested
    | _ -> []

type private EmitterRevisionDecl =
    { Revision: string
      Axes: string list
      Kinds: string list
      ControlKinds: string list
      OpKinds: string list
      Vectors: string list }

let private stringsOf (el: JsonElement) (name: string) : string list =
    match el.TryGetProperty name with
    | true, arr when arr.ValueKind = JsonValueKind.Array ->
        arr.EnumerateArray() |> Seq.map (fun s -> string (s.GetString())) |> List.ofSeq
    | _ -> failwithf "emitter profile member '%s' is missing or not an array" name

/// The declared lineages: (name, oldestAccepted by host, revisions oldest first).
let private emitterLineages: (string * Map<string, string> * EmitterRevisionDecl list) list =
    use doc =
        JsonDocument.Parse(File.ReadAllText(Path.Combine(corpusRoot, "manifest.json")), Corpus.wireJsonOptions)

    match doc.RootElement.TryGetProperty "emitterProfiles" with
    | true, profiles when profiles.ValueKind = JsonValueKind.Object ->
        [ for lineage in profiles.EnumerateObject() do
              let oldest =
                  lineage.Value.GetProperty("oldestAccepted").EnumerateObject()
                  |> Seq.map (fun p -> p.Name, string (p.Value.GetString()))
                  |> Map.ofSeq

              let revisions =
                  [ for r in lineage.Value.GetProperty("revisions").EnumerateArray() do
                        let subset = r.GetProperty "subset"

                        { Revision = string (r.GetProperty("id").GetString())
                          Axes = stringsOf r "axes"
                          Kinds = stringsOf subset "kinds"
                          ControlKinds = stringsOf subset "formFieldKinds"
                          OpKinds = stringsOf subset "ops"
                          Vectors = stringsOf r "vectors" } ]

              lineage.Name, oldest, revisions ]
    | _ -> []

let private entryById = corpusEntries |> List.map (fun e -> e.Id, e) |> Map.ofList

let private trimEol (s: string) = s.TrimEnd('\n')

/// Every reason `bytes` (of a row read by `decoder`) falls outside `r`, or [].
let private subsetDefects (r: EmitterRevisionDecl) (decoder: string) (bytes: string) : string list =
    let policy = Fuaran.UI.KindPolicy.DecodePolicy.admitting r.Revision r.Kinds

    let kindDefect =
        let result =
            if decoder = "op" then
                JsonDecode.decodeOpWithPolicy policy bytes |> Result.map ignore
            else
                JsonDecode.decodeNodeObjWithPolicy policy bytes |> Result.map ignore

        match result with
        | Ok() -> []
        | Error e -> [ sprintf "a node kind outside the subset: %s at %s (%s)" e.Code e.Path e.Message ]

    let controls =
        Corpus.controlKindsIn bytes
        |> List.filter (fun k -> not (List.contains k r.ControlKinds))
        |> List.map (sprintf "a form-field kind outside the subset: %s")

    let ops =
        if decoder = "op" then
            use doc = JsonDocument.Parse(bytes, Corpus.wireJsonOptions)

            opTagsOf doc.RootElement
            |> List.filter (fun t -> not (List.contains t r.OpKinds))
            |> List.map (sprintf "an op outside the subset: %s")
        else
            []

    kindDefect @ controls @ ops

/// Every reason the vector `id` fails revision `r`'s bar on this host, or [].
let private vectorDefects (r: EmitterRevisionDecl) (id: string) : string list =
    match Map.tryFind id entryById with
    | None -> [ "names no row of the manifest" ]
    | Some e when not (Corpus.emitterVectorKinds.Contains e.Kind) ->
        [ sprintf "is a %s row, not a family every codec host reads" e.Kind ]
    | Some e ->
        let input = Corpus.readPayload corpusRoot e.InputFile |> trimEol

        let expected =
            e.ExpectedFile |> Option.map (Corpus.readPayload corpusRoot >> trimEol)

        let integer =
            if List.contains "integer-only" r.Axes && carriesNonIntegerNumber input then
                [ "carries a number token with a fraction or an exponent under integer-only" ]
            else
                []

        let accepted =
            let reencoded =
                if e.Decoder = "op" then
                    JsonDecode.decodeOp input
                    |> Result.map Fuaran.UI.OpStream.Abstractions.CanonicalJson.encodeOp
                else
                    JsonDecode.decodeNodeObj input
                    |> Result.map Fuaran.UI.OpStream.Abstractions.CanonicalJson.encodeNode

            match reencoded, expected with
            | Error err, _ -> [ sprintf "is NOT accepted: %s at %s (%s)" err.Code err.Path err.Message ]
            | Ok _, None -> [ "carries no expected file" ]
            | Ok bytes, Some want when bytes <> want -> [ "re-encodes to bytes other than its expected file" ]
            | Ok _, Some _ -> []

        let schemaValid =
            match expected |> Option.map validate with
            | Some(Some true) -> []
            | _ -> [ "its canonical form does not validate against schema.json" ]

        integer @ subsetDefects r e.Decoder input @ accepted @ schemaValid

let private opPayloads (revisions: EmitterRevisionDecl list) =
    revisions
    |> List.collect _.Vectors
    |> List.distinct
    |> List.choose (fun id -> Map.tryFind id entryById)
    |> List.filter (fun e -> e.Kind = "op-round-trip")
    |> List.map (fun e -> e, Corpus.readPayload corpusRoot e.InputFile |> trimEol)

[<Tests>]
let emitterAcceptance =
    testList
        "Phase 2451 — the constrained-emitter acceptance leg (WIRE_FORMAT 11.4)"
        [ test "the corpus declares at least one emitter-profile lineage" {
              Expect.isNonEmpty
                  emitterLineages
                  "manifest.json declares no emitterProfiles — the leg would read nothing, which is not a pass"
          }

          test "every lineage's oldestAccepted names exactly the roster's codec hosts, each a revision of it" {
              use roster =
                  JsonDocument.Parse(File.ReadAllText(Path.Combine(corpusRoot, "conformance", "roster.json")))

              let codecHosts =
                  roster.RootElement.GetProperty("hosts").EnumerateArray()
                  |> Seq.filter (fun h -> h.GetProperty("role").GetString() = "codec")
                  |> Seq.map (fun h -> string (h.GetProperty("id").GetString()))
                  |> Set.ofSeq

              for (name, oldest, revisions) in emitterLineages do
                  Expect.equal
                      (oldest |> Map.keys |> Set.ofSeq)
                      codecHosts
                      (sprintf "lineage %s: oldestAccepted must name every codec host of the roster and no other" name)

                  for KeyValue(host, rev) in oldest do
                      Expect.isTrue
                          (revisions |> List.exists (fun r -> r.Revision = rev))
                          (sprintf "lineage %s: oldestAccepted[%s] = %s names no revision of it" name host rev)
          }

          test "every lineage's newest revision declares only tags the corpus attests" {
              let kinds = Corpus.loadKinds () |> Set.ofList
              let controls = Corpus.loadFormFieldKinds () |> Set.ofList
              let ops = Corpus.loadOps () |> Set.ofList

              for (name, _, revisions) in emitterLineages do
                  let newest = List.last revisions

                  let stray =
                      (newest.Kinds |> List.filter (kinds.Contains >> not))
                      @ (newest.ControlKinds |> List.filter (controls.Contains >> not))
                      @ (newest.OpKinds |> List.filter (ops.Contains >> not))

                  Expect.isEmpty
                      stray
                      (sprintf "lineage %s: %s declares tags outside the attested vocabularies" name newest.Revision)
          }

          // A `kind.$type` names one family only while the two vocabularies stay
          // disjoint; the form-field check reads control positions, the node-kind
          // check reads node positions, and this pins that no tag could be both.
          test "the NodeKind and FormFieldKind vocabularies share no tag" {
              let shared =
                  Set.intersect (Corpus.loadKinds () |> Set.ofList) (Corpus.loadFormFieldKinds () |> Set.ofList)

              Expect.isEmpty shared "a tag names both a node kind and a control kind"
          }

          for (name, oldest, revisions) in emitterLineages do
              let from =
                  match Map.tryFind thisHost oldest with
                  | Some rev -> rev
                  | None -> failwithf "lineage %s records no oldestAccepted for %s" name thisHost

              let index = revisions |> List.findIndex (fun r -> r.Revision = from)

              for r in List.skip index revisions do
                  test (sprintf "%s: every vector is accepted under its declaration" r.Revision) {
                      Expect.isNonEmpty r.Vectors (sprintf "%s names no vector" r.Revision)

                      let failures =
                          [ for v in r.Vectors do
                                for d in vectorDefects r v do
                                    yield sprintf "%s %s" v d ]

                      Expect.isEmpty failures (sprintf "%s fails its bar on %s" r.Revision thisHost)
                  }

          // Go-red: each check above can fail.
          test "the integer-only scanner refuses a fraction and an exponent, and ignores strings" {
              Expect.isTrue (carriesNonIntegerNumber """{"v":2.0}""") "2.0 is a fraction token"
              Expect.isTrue (carriesNonIntegerNumber """{"v":[1E+21]}""") "1E+21 is an exponent token"
              Expect.isFalse (carriesNonIntegerNumber """{"v":"1.5e3","w":-7}""") "a string is not a number token"
          }

          test "the subset check refuses a frame carrying a kind, a control or an op outside it" {
              for (name, _, revisions) in emitterLineages do
                  let newest = List.last revisions
                  let frames = opPayloads [ newest ]
                  Expect.isNonEmpty frames (sprintf "lineage %s carries no frame to perturb" name)

                  for (e, bytes) in frames do
                      Expect.isEmpty (subsetDefects newest e.Decoder bytes) (sprintf "%s is inside its subset" e.Id)

                      use doc = JsonDocument.Parse(bytes, Corpus.wireJsonOptions)
                      let own = (opTagsOf doc.RootElement).Head

                      let narrowed =
                          { newest with
                              OpKinds = newest.OpKinds |> List.filter ((<>) own) }

                      Expect.isNonEmpty
                          (subsetDefects narrowed e.Decoder bytes)
                          (sprintf "%s admitted without %s" e.Id own)

                  for (e, bytes) in frames do
                      for k in Corpus.controlKindsIn bytes do
                          let narrowed =
                              { newest with
                                  ControlKinds = newest.ControlKinds |> List.filter ((<>) k) }

                          Expect.isNonEmpty
                              (subsetDefects narrowed e.Decoder bytes)
                              (sprintf "%s admitted without the control %s" e.Id k)

                      for k in newest.Kinds do
                          if bytes.Contains(sprintf "\"$type\":\"%s\"" k) then
                              let narrowed =
                                  { newest with
                                      Kinds = newest.Kinds |> List.filter ((<>) k) }

                              Expect.isNonEmpty
                                  (subsetDefects narrowed e.Decoder bytes)
                                  (sprintf "%s admitted without the kind %s" e.Id k)
          } ]
